INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427242, 16593, 'BBC News', 'en', '97-year-old woman rescued after Nepali floods looked like ''a warrior''', 'https://www.bbc.co.uk/news/videos/cj64kgrpgjdo', 'A 97-year-old woman, Guna Maya Bohara, survived the flash floods and was rescued using an excavator.', 'https://ichef.bbci.co.uk/ace/standard/240/cpsprodpb/983c/live/3900eaa0-a318-11f1-aed2-8d6da8d75094.jpg', '2026-08-28T21:17:54+00:00', '2026-08-29T00:03:08.771306'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427251, 16593, 'The Guardian', 'en', 'At least 93,000 ‘in great need’ after Nepal-Tibet flash floods, says Red Cross', 'https://www.theguardian.com/world/2026/aug/28/nepal-tibet-flash-floods-red-cross-rescuers-death-toll', 'Federation says it fears death toll of nearly 600 will continue to rise as rescuers reach cut-off areas Nepal-Tibet flash flood – latest updates Visual guide: how the deadly flooding unfolded Tell us: have you been affected by the flash floods? The Red Cross has said at least 93,000 people may have been affected by Wednesday’s flash floods on the Nepal-Tibet border, which have killed nearly 600 people, left another 1,900 missing, and triggered a huge rescue operation that is being hampered by fears of new flooding. The International Federation of Red Cross and Red Crescent Societies (IFRC), th', 'https://i.guim.co.uk/img/media/801126947c8d8ca4588da62c64e532997fb1a82b/842_378_2721_2176/master/2721.jpg?width=140&quality=85&auto=format&fit=max&s=2c7938ed9867377e259a29c685f3bfd2', '2026-08-28T15:55:41+00:00', '2026-08-29T00:03:19.694291'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427252, 16593, 'The Guardian', 'en', 'Families of 33 missing Britons rush to Nepal as fears grow of more floods', 'https://www.theguardian.com/world/2026/aug/28/families-missing-britons-nepal-flash-floods', 'Desperate relatives trying to reach loved ones last seen in area where entire villages have been swept away Nepal-Tibet flash flood – latest updates Visual guide: how the deadly flooding unfolded Tell us: have you been affected by the flash floods? Families are rushing to Nepal to search for the 33 British nationals who are still missing, as fears mount over the risk of a second wave of flooding in the region. The catastrophic flash floods that hit Nepal and Tibet on Wednesday , thundering down valleys and sweeping away entire villages, have killed at least 538 people, while more than 1,500 re', 'https://i.guim.co.uk/img/media/b8b087079ca3e898d252c98b7dd352ece06e5f17/0_0_5000_4000/master/5000.png?width=140&quality=85&auto=format&fit=max&s=a0db2bfd405059366376d13824d2b6ef', '2026-08-28T15:44:38+00:00', '2026-08-29T00:03:19.718794'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427253, 16593, 'The Guardian', 'en', 'Number of Australians missing in Nepal’s deadly floods rises again, as Albanese deploys more personnel', 'https://www.theguardian.com/world/2026/aug/29/australians-missing-nepal-floods-total-rises-albanese-dfat-personnel-arriving', 'There are now 41 Australians missing, and four rapid response team members are expected to arrive in Kathmandu At least 93,000 ‘in great need’ after Nepal-Tibet flash floods How the deadly Nepal and Tibet flash flood unfolded – a visual guide Get our breaking news email , free app or daily news podcast The number of Australians who were reported missing in the catastrophic Nepal flooding disaster has risen to 41, as one family celebrates after an unaccounted-for woman made contact with them yesterday. It means three additional Australians were confirmed missing overnight – up from 38 who remai', 'https://i.guim.co.uk/img/media/00bc3a6f28120010da82b2d0ba9dd72d6e740880/767_0_3833_3067/master/3833.jpg?width=140&quality=85&auto=format&fit=max&s=6d8c6c68fcf618211c94620432dad3e0', '2026-08-28T22:53:57+00:00', '2026-08-29T00:03:19.757982'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427258, 16593, 'The Guardian', 'en', 'Chinese control of information hampers assessment of Tibet flood damage', 'https://www.theguardian.com/world/2026/aug/28/chinese-controls-information-hamper-assessment-tibet-flood-damage', 'Scale of devastation emerges in Nepal as reporters reach disaster area, but Chinese state media focus more on rescue efforts Nepal-Tibet flash flood – latest updates In the days since an enormous glacier in the Himalayas snapped away from a mountaintop and cascaded into the valley below, the true scale of the devastation caused by the flash floods in Nepal and Tibet is still unfolding. But the picture is emerging far more quickly in Nepal than in China, where strict controls on the flow of information from one of its most sensitive regions are hampering the public’s understanding of events. Co', 'https://i.guim.co.uk/img/media/3d9b134af42fcf5be0c903258ae03d2147807bb0/995_562_2814_2251/master/2814.jpg?width=140&quality=85&auto=format&fit=max&s=1a8dc40e8234b995847e749f35fed3a5', '2026-08-28T14:25:44+00:00', '2026-08-29T00:03:19.955689'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
