INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427407, 16593, 'France 24', 'en', '🔴Nepal-Tibet floods live: Death toll passes 580, nearly 2,500 people missing', 'https://www.france24.com/en/asia-pacific/20260828-nepal-tibet-live-china-warns-lake-formed-by-mudslide-on-nepal-border-could-breach', '', '', '2026-08-28T17:06:15+00:00', '2026-08-29T00:03:43.237950'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427408, 16593, 'France 24', 'en', 'Nepal: ''Region has hundreds of high-altitude lakes prone to unleashing enormous volumes of water''', 'https://www.france24.com/en/video/20260828-nepal-region-has-hundreds-of-high-altitude-lakes-prone-to-unleashing-enormous-volumes-of-water', 'William Hilderbrandt is pleased to welcome David Fisher, Head of Delegation, Nepal International Federation of Red Cross. The scale of Nepal’s disaster cannot yet be fully measured. Entire communities remain difficult to reach, tens of thousands of people have been affected, and official assessments are only beginning. But the central challenge is already clear: this cannot be treated solely as an immediate humanitarian emergency. What happens to these communities in the years ahead depends heavily on what we do now. Emergency relief must be accompanied from the outset by planning, funding and', 'https://s.france24.com/media/display/4da191b4-a2fd-11f1-a486-005056a90284/w:1024/p:16x9/EN-20260828-131412-132208-CS.jpg', '2026-08-28T16:57:59+00:00', '2026-08-29T00:03:43.271598'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427409, 16593, 'France 24', 'en', 'Nepal: Families cling to hope as nearly 1,000 remain missing', 'https://www.france24.com/en/nepal-families-cling-to-hope-as-nearly-1-000-remain-missing', 'Nepal''s confirmed death toll has risen to at least 538, but families are still searching hospitals and disaster zones in the hope their loved ones will be found alive, with nearly 1,000 people still missing. More than 3,700 people have been rescued so far, though destroyed roads, bridges and thick mud continue to hamper search efforts.', 'https://s.france24.com/media/display/d92d8b2e-a2fe-11f1-8dce-005056bfb2b6/w:1024/p:16x9/EN-20260828-170152-170321-CS.jpg', '2026-08-28T16:56:39+00:00', '2026-08-29T00:03:43.289466'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427411, 16593, 'France 24', 'en', 'Nepal: Relief camp shelters grieving families', 'https://www.france24.com/en/nepal-relief-camp-shelters-grieving-families', 'Around 500 people are sheltering at a monastery-turned-relief camp in northern Kathmandu, where many families are still in shock after losing their homes and loved ones in the devastating Nepal floods. FRANCE 24''s Shahzaib Wahlah reports from the camp as rescue teams continue searching for nearly 1,000 missing people, with operations set to continue through the night.', 'https://s.france24.com/media/display/f19d2d20-a1e8-11f1-90f9-005056a97e36/w:1024/p:16x9/2026-08-27T054155Z-1329930245-RC2T6NALUMIO-RTRMADP-3-NEPAL-FLOODS.jpg', '2026-08-28T16:20:59+00:00', '2026-08-29T00:03:43.335980'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427416, 16593, 'France 24', 'en', 'Rescuers grapple with mountain of challenges after the Nepal-Tibet floods', 'https://www.france24.com/en/asia-pacific/20260828-rescuers-grapple-with-mountain-of-challenges-after-the-nepal-tibet-floods', 'Emergency services are rushing to find survivors and treat the wounded after a devastating flash flood on the border of Nepal and Tibet on Wednesday killed more than 500 people, with over a thousand still missing. But the remote and rugged terrain, as well as the risk of further flooding from upstream lakes formed by piles of debris, make their work as delicate as it is dangerous.', 'https://s.france24.com/media/display/66f1c974-a21a-11f1-b5fb-005056bf30b7/w:1024/p:16x9/rescue-nepal.jpg', '2026-08-28T14:14:00+00:00', '2026-08-29T00:03:43.427689'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427420, 16593, 'France 24', 'en', 'Nepal floods explained: The chain of events behind the disaster', 'https://www.france24.com/en/nepal-floods-explained-the-chain-of-events-behind-the-disaster', 'A glacier broke apart. An ice and rock avalanche followed. Then came an earthquake, before a landslide triggered devastating floods that tore through kilometres of valley. This is what happened along the Nepal-China border, where rescue teams are still trying to recover survivors 48 hours after the catastrophe. FRANCE 24 breaks down the chain of events and the scientific explanations behind the disaster.', 'https://s.france24.com/media/display/30b8c788-a15a-11f1-b017-005056a90284/w:1024/p:16x9/AP26238334534782.jpg', '2026-08-28T12:48:06+00:00', '2026-08-29T00:03:43.529644'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427423, 16593, 'France 24', 'en', '''Ran for our lives'': Flood survivors recount terrifying escape from Nepal-Tibet disaster', 'https://www.france24.com/en/asia-pacific/20260828-ran-for-our-lives-flood-survivors-recount-terrifying-escape-from-nepal-tibet-disaster', 'Survivors of the catastrophic flash floods in Nepal and Tibet, some still missing friends and family members, shared harrowing accounts of their escape from raging floodwaters that brought devastation to the Himalayan border region, leaving more than 550 people dead and some 1,500 missing.', 'https://s.france24.com/media/display/c4877f86-a2a4-11f1-8c93-005056bf30b7/w:1024/p:16x9/a445c491a2511f5d6e49b86a241ebbb831600f74.jpg', '2026-08-28T11:55:15+00:00', '2026-08-29T00:03:43.609252'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
